  };

  // The letter fallback is the canned glyph, which ALWAYS exists (as `•`
  // for an unregistered provider) - except that a bullet renders nothing at
  // 12px, so an unknown provider keeps the identifier's first two letters.
  const fallbackText = $derived(
    curatedGlyph(provider) === "\u{2022}" ? provider.slice(0, 2).toUpperCase() : curatedGlyph(provider)
  );
  // v25 F1: the fallback was a hardcoded `#1e2435` - a dark-mode border color
  // used as a fill, so an unknown provider rendered as a near-invisible circle
  // on a light page. `--surface-hover` is the neutral avatar fill for both
  // themes. `brandColors` above stays literal on purpose: those ARE brand
  // identities and must not retheme.
  const bgColor = $derived(brandColors[provider] || "var(--surface-hover)");
  const logoPath = $derived(logos[provider]);

  // The letter fallback sits on a brand fill, so its ink is whichever of white
  // or black clears more contrast on that fill (white fails on Google blue).
  const fallbackColor = $derived(brandColors[provider] ? inkFor(brandColors[provider]) : "rgb(var(--text-rgb))");
</script>

<div
  class="rounded-full flex items-center justify-center {dims[size]} shrink-0"
  style="background-color: {bgColor};"
  aria-hidden="true"
>
  {#if logoPath}
    <svg class={svgSize[size]} viewBox="0 0 24 24" fill="white" xmlns="http://www.w3.org/2000/svg">
      {@html logoPath}
    </svg>
  {:else}
    <span class="text-xs font-bold" style="color: {fallbackColor};">{fallbackText}</span>
  {/if}
</div>
